import{_ as s,o as a,c as t,a3 as o}from"./chunks/framework.ClKfp1vE.js";const u=JSON.parse('{"title":"Recipes","description":"","frontmatter":{"title":"Recipes","editLink":false},"headers":[],"relativePath":"api/plugin-sdk/recipes.md","filePath":"api/plugin-sdk/recipes.md","lastUpdated":1786517010000}'),n={name:"api/plugin-sdk/recipes.md"};function i(r,e,d,l,c,p){return a(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="recipes" tabindex="-1">Recipes <a class="header-anchor" href="#recipes" aria-label="Permalink to &quot;Recipes&quot;">​</a></h1><p>Patterns copied from in-tree plugins (cookies→csrf, pools, tasks, store).</p><blockquote><p>Author guide — edit <code>docs/.vitepress/plugin-sdk-guides/recipes.md</code>, then <code>pnpm docs:generate</code>.</p></blockquote><p>Recipes distilled from in-tree plugins. Full app docs: <a href="/sova/plugins/">Plugins</a>.</p><h3 id="_1-marker-dependent-mw-cookies-→-session-→-csrf" tabindex="-1">1. Marker + dependent MW (cookies → session → csrf) <a class="header-anchor" href="#_1-marker-dependent-mw-cookies-→-session-→-csrf" aria-label="Permalink to &quot;1. Marker + dependent MW (cookies → session → csrf)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Cookies::install  → state(CookieLayerPresent) + named(&quot;cookies&quot;)</span></span>
<span class="line"><span>Session::install  → soft-install cookies if missing</span></span>
<span class="line"><span>                  → state(SessionStoreHandle)</span></span>
<span class="line"><span>                  → named(&quot;session&quot;) + with_state</span></span>
<span class="line"><span>                  → routes.with(Needs::&lt;CookieLayerPresent&gt;)</span></span>
<span class="line"><span>Csrf::install     → requires([&quot;session&quot;])</span></span>
<span class="line"><span>                  → named(&quot;csrf&quot;) + with_state</span></span></code></pre></div><p><strong>Use when:</strong> layered HTTP concerns with hard ordering.</p><h3 id="_2-leaked-security-headers-cors-shield" tabindex="-1">2. Leaked security headers (cors / shield) <a class="header-anchor" href="#_2-leaked-security-headers-cors-shield" aria-label="Permalink to &quot;2. Leaked security headers (cors / shield)&quot;">​</a></h3><p>Builder + toml unset-fill → <code>named(..., with_leaked(cfg, …))</code> mutating response headers / answering OPTIONS.</p><p><strong>Use when:</strong> config is immutable after boot; zero Arc churn.</p><h3 id="_3-pool-lifecycle-redis-db" tabindex="-1">3. Pool lifecycle (redis / db) <a class="header-anchor" href="#_3-pool-lifecycle-redis-db" aria-label="Permalink to &quot;3. Pool lifecycle (redis / db)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>state(Pool::empty)</span></span>
<span class="line"><span>on_startup: connect + ping (Err if URL empty)</span></span>
<span class="line"><span>on_shutdown: clear</span></span>
<span class="line"><span>register_check: ping</span></span>
<span class="line"><span>optional: inject_conn MW (db)</span></span>
<span class="line"><span>optional: register_cli migrate/seed (db)</span></span></code></pre></div><p><strong>Use when:</strong> shared network resource must be ready before traffic.</p><h3 id="_4-library-crate-thin-facade-plugin-store" tabindex="-1">4. Library crate + thin facade plugin (store) <a class="header-anchor" href="#_4-library-crate-thin-facade-plugin-store" aria-label="Permalink to &quot;4. Library crate + thin facade plugin (store)&quot;">​</a></h3><p><code>sova-store</code> is mostly a library (<code>KvStore</code>, <code>Cache</code>). Facade <code>SharedStore</code> plugin id <code>&quot;store&quot;</code> only does <code>app.state(AppStore)</code>.</p><p><strong>Use when:</strong> most consumers need types without install, but apps want one shared handle.</p><h3 id="_5-non-plugin-helpers-env-sse" tabindex="-1">5. Non-plugin helpers (env, sse) <a class="header-anchor" href="#_5-non-plugin-helpers-env-sse" aria-label="Permalink to &quot;5. Non-plugin helpers (env, sse)&quot;">​</a></h3><ul><li><code>sova-env</code>: call <code>load()</code> before building <code>App</code></li><li><code>sova-sse</code>: <code>app.state(SseChannel::new())</code> manually; helpers build <code>Response</code></li></ul><p><strong>Use when:</strong> no middleware/registry needed — avoid fake <code>Plugin</code> wrappers.</p><h3 id="_6-background-worker-tasks" tabindex="-1">6. Background worker (tasks) <a class="header-anchor" href="#_6-background-worker-tasks" aria-label="Permalink to &quot;6. Background worker (tasks)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>state(registry + TaskBackend)</span></span>
<span class="line"><span>register_check / register_cli</span></span>
<span class="line"><span>optional POST /_tasks/enqueue (guarded)</span></span>
<span class="line"><span>service(scheduler)</span></span>
<span class="line"><span>service(worker)  // wait_shutdown loops</span></span></code></pre></div><p>Emit <code>tracing</code> with <code>target: &quot;sova.tasks&quot;</code> if DevTools should show Jobs.</p><h3 id="_7-soft-feature-hooks-devtools" tabindex="-1">7. Soft feature hooks (devtools) <a class="header-anchor" href="#_7-soft-feature-hooks-devtools" aria-label="Permalink to &quot;7. Soft feature hooks (devtools)&quot;">​</a></h3><p>Compile-time <code>#[cfg(feature = &quot;session&quot;)]</code> etc. After <code>next</code>, read extensions if present. Log hook parses known targets. <code>logger_skip_path</code> for panel routes. Release builds hard-off unless env escape hatch.</p><h3 id="_8-outbound-client-http" tabindex="-1">8. Outbound client (http) <a class="header-anchor" href="#_8-outbound-client-http" aria-label="Permalink to &quot;8. Outbound client (http)&quot;">​</a></h3><p><code>state(HttpClient)</code> + named configs from toml; propagate <code>request_id</code>; respect <code>Deadline</code> / SSRF guards; structured <code>http.client</code> spans for DevTools HTTP tab.</p><h3 id="choosing-a-shape" tabindex="-1">Choosing a shape <a class="header-anchor" href="#choosing-a-shape" aria-label="Permalink to &quot;Choosing a shape&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Need</th><th>Shape</th></tr></thead><tbody><tr><td>Global MW + config</td><td>Plugin + <code>named</code> / <code>with_leaked</code> / <code>with_state</code></td></tr><tr><td>Shared pool</td><td>Plugin + lifecycle + check</td></tr><tr><td>Pure helpers</td><td>Library module, no Plugin</td></tr><tr><td>Optional integration</td><td>Soft <code>try_state</code> / Cargo feature</td></tr><tr><td>Must have dep</td><td><code>requires</code> + docs</td></tr></tbody></table>`,28)])])}const g=s(n,[["render",i]]);export{u as __pageData,g as default};
